<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Account Appeal | BloodNexus</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{min-height:100vh;background:radial-gradient(circle at 15% 15%,#ffe4e6,transparent 35%),radial-gradient(circle at 90% 80%,#fecdd3,transparent 30%),linear-gradient(135deg,#0b1220,#172033);display:grid;place-items:center;font-family:Inter,system-ui}.cardx{width:min(620px,92vw);background:rgba(255,255,255,.97);border-radius:28px;padding:32px;box-shadow:0 30px 80px rgba(0,0,0,.28)}.brand{color:#dc2638;font-weight:900;font-size:22px}.status{border-radius:18px;padding:18px;margin:18px 0}.pending{background:#fff7ed;border:1px solid #fed7aa}.approved{background:#ecfdf5;border:1px solid #a7f3d0}.rejected{background:#fff1f2;border:1px solid #fecdd3}.muted{color:#64748b;font-size:13px}.pill{display:inline-block;padding:6px 12px;border-radius:999px;font-size:11px;font-weight:900}</style></head><body><div class="cardx"><div class="brand">🩸 BloodNexus Security</div><h2 class="mt-3 fw-bold">Track Account Appeal</h2><p class="muted">Only one appeal can ever be submitted for an email address. After submission, this page is used to track the final decision.</p>@if(session('status'))<div class="alert alert-info rounded-4">{{session('status')}}</div>@endif
